parameters.jsCode:
const items = $input.all();
let text = '';

for (const item of items) {
  if (item.json.content) {
    text += item.json.content + '\n';
  }
}

const userMessage = $node["Webhook"].json.body.message || '';
const customerData = $node["Webhook"].json.body.customer_data || null;

return [{
  json: {
    knowledge_base: text,
    user_message: userMessage,
    customer_data: customerData
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  system_instruction: {
    parts: [{ text: $json.system_prompt }]
  },
  contents: [
    {
      role: "user",
      parts: [{ text: $json.user_message }]
    }
  ],
  generationConfig: {
    temperature: 0.7,
    maxOutputTokens: 400
  }
}) }}

parameters.responseBody:
={{ JSON.stringify({
  reply: $node["Gemini Flash API"].json.candidates?.[0]?.content?.parts?.[0]?.text || "Thanks for your message! How can I assist you with your room search today?",
  trigger_form: ($node["Gemini Flash API"].json.candidates?.[0]?.content?.parts?.[0]?.text || "").toLowerCase().includes("booking form") || ($node["Gemini Flash API"].json.candidates?.[0]?.content?.parts?.[0]?.text || "").toLowerCase().includes("booking request"),
  buttons: (($node["Gemini Flash API"].json.candidates?.[0]?.content?.parts?.[0]?.text || "").toLowerCase().includes("booking form") || ($node["Gemini Flash API"].json.candidates?.[0]?.content?.parts?.[0]?.text || "").toLowerCase().includes("booking request")) ? [
    {
      label: "📅 Submit a booking request",
      action: "open_form",
      url: "https://forms.fillout.com/t/gq1XFEqEWJus"
    }
  ] : []
}) }}
